{
  "updates": [
    {
      "question_id": "Q1",
      "answered_aspects": [
        {
          "aspect_id": "Q1-A1",
          "claim": "『頭』指秦子羽的头，是张敏《头责子羽文》中拟人化的角色；刘孝标注引文提供了头责备子羽的具体叙事框架。",
          "evidence": [
            {
              "ref": "L10",
              "quote": "張敏集載頭責子羽文曰余"
            },
            {
              "ref": "L14",
              "quote": "頭責子羽曰吾託子為頭萬有餘日矣大塊禀我以"
            },
            {
              "ref": "J08",
              "quote": "有張敏者，太原人，仕歷平南參軍、太子舍人、濟北長史。其一篇曰頭責子羽文，極為尖新。"
            }
          ]
        }
      ],
      "unanswered_aspects": [],
      "conflicts": [],
      "reading_sufficient": true,
      "historical_verification_open": false
    },
    {
      "question_id": "Q2",
      "answered_aspects": [
        {
          "aspect_id": "Q2-A1",
          "claim": "『士卿』是刘许的官称（宗正卿），不是另一个人名；刘许字文生，与张华同范阳人。",
          "evidence": [
            {
              "ref": "L05",
              "quote": "故曰士卿互其辞也宗正卿或曰士卿/恵帝時為宗正卿按許與張華同范陽人"
            },
            {
              "ref": "J03",
              "quote": "臣松之案：頭責子羽曰『士卿劉許』，字文生，正之弟也。與張華六人，並稱文辭可觀，意思詳序。晉惠帝世，許為越騎校尉。"
            }
          ]
        },
        {
          "aspect_id": "Q2-A2",
          "claim": "刘许字文生，是刘正之弟，见裴松之《三国志注》所引《头责子羽文》的说法。",
          "evidence": [
            {
              "ref": "J03",
              "quote": "臣松之案：頭責子羽曰『士卿劉許』，字文生，正之弟也。"
            }
          ]
        }
      ],
      "unanswered_aspects": [],
      "conflicts": [
        {
          "conflict_id": "Q2-C1",
          "description": "关于刘许在晋惠帝时的官职，刘孝标注称『惠帝时为宗正卿』，而裴松之注称『晋惠帝世，许为越骑校尉』，两说不同。",
          "evidence": [
            {
              "ref": "L05",
              "quote": "恵帝時為宗正卿按許與張華同范陽人"
            },
            {
              "ref": "J03",
              "quote": "晉惠帝世，許為越騎校尉。"
            }
          ]
        },
        {
          "conflict_id": "Q2-C2",
          "description": "刘许的郡望存在冲突：L04称『鹿郡人』（又言『文生涿』），L05称『按许与张华同范阳人』。",
          "evidence": [
            {
              "ref": "L04",
              "quote": "鹿郡人父放魏驃騎將軍許/晉百官名曰劉許字文生涿"
            },
            {
              "ref": "L05",
              "quote": "按許與張華同范陽人"
            }
          ]
        }
      ],
      "reading_sufficient": true,
      "historical_verification_open": true
    },
    {
      "question_id": "Q3",
      "answered_aspects": [],
      "unanswered_aspects": [
        {
          "aspect_id": "Q3-U1",
          "gap": "缺少对『天府』实际所指的说明，无法确定是指朝廷、官府还是天宫，影响对『攀龙附凤』隐喻方向及整则故事讽刺意图的判断。",
          "reading_impact": "high"
        }
      ],
      "conflicts": [],
      "reading_sufficient": false,
      "historical_verification_open": false
    }
  ]
}

